async function api<T>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`/api${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...options?.headers } });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Request failed');
  return result as T;
}
const post = (body?: unknown): RequestInit => ({ method: 'POST', ...(body !== undefined ? { body: JSON.stringify(body) } : {}) });
const percent = (a: number, b: number) => b ? Math.round(a / b * 100) : 0;
const number = (n: number) => n.toLocaleString();
const platformPost = <T,>(path: string, body?: unknown) => api<T>(`/platform${path}`, post(body));
const date = (s: string) => new Date(s).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
function ago(s: string) { const m = Math.max(0, Math.floor((Date.now() - new Date(s).getTime()) / 60000)); return m < 1 ? 'Just now' : m < 60 ? `${m}m ago` : m < 1440 ? `${Math.floor(m / 60)}h ago` : `${Math.floor(m / 1440)}d ago`; }
function Status({ status }: { status: string }) { return <span className={`status status-${status}`}><span />{({ success: 'Exploited', blocked: 'Blocked', error: 'Error', running: 'Running', completed: 'Completed', stopped: 'Stopped', failed: 'Failed' } as Record<string, string>)[status] || status}</span>; }
function Severity({ value }: { value: string }) { return <span className={`severity ${value}`}><span />{value}</span>; }
function TargetAvatar({ target, small = false }: { target?: Target; small?: boolean }) { return <span className={`target-avatar ${target?.color || 'blue'} ${small ? 'small' : ''}`}><Bot size={small ? 15 : 21} /></span>; }
function Empty({ title, description, icon: Icon = Search }: { title: string; description: string; icon?: typeof Search }) { return <div className="empty"><div className="empty-icon"><Icon size={26} /></div><h3>{title}</h3><p>{description}</p></div>; }
function Sparkline({ values, color = 'lime' }: { values: number[]; color?: string }) {
  const max = Math.max(...values, 1);
  const points = values.map((v, i) => `${i * 13},${36 - v / max * 30}`).join(' ');
  return <svg className={`sparkline ${color}`} viewBox={`0 0 ${(values.length - 1) * 13} 42`} aria-hidden="true"><path d={`M ${points.replaceAll(' ', ' L ')} L ${(values.length - 1) * 13} 42 L 0 42 Z`} fill="currentColor" opacity=".08" /><polyline points={points} fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" /></svg>;
}

export default function App() {
  return window.location.pathname === '/landing' ? <LandingPage /> : <Workbench />;
}

function LandingPage() {
  const [intro, setIntro] = useState(() => {
    try { return !window.matchMedia('(prefers-reduced-motion: reduce)').matches && sessionStorage.getItem('agentbreak-veo-intro-seen') !== '1'; }
    catch { return false; }
  });
  const finishIntro = () => { try { sessionStorage.setItem('agentbreak-veo-intro-seen', '1'); } catch { /* Storage may be unavailable. */ } setIntro(false); };
  return <ApprovedLanding intro={intro ? <CinematicIntro onSkip={finishIntro} onComplete={finishIntro} /> : null} />;
}

