  useEffect(() => { void refresh(); const timer = setInterval(() => void refresh(), 1800); return () => clearInterval(timer); }, []);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const handler = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); searchRef.current?.focus(); } if (e.key === 'Escape') { setSelectedTrace(null); setSelectedPlatformRun(null); setShowCampaign(false); setDocs(false); setMobile(false); } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler); }, []);
  const navigate = (p: Page) => { setPage(p); setMobile(false); setSearch(''); setSelectedCampaign(''); setSurfaceFilter('all'); setOutcomeFilter('all'); setSeverityFilter('all'); };
